contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address _target, uint _value, bytes memory _data) public {
        require(address(c).balance >= _value, "insufficient contract balance");
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The low-level call in C.sendMoney returns a success flag; C reverts iff that flag is false.
        // When the call succeeds, value is transferred to _target and C's balance decreases by _value.
        // When it reverts, C's balance is unchanged.
        assert(!reverted || address(c).balance == beforeBalance);
    }
}

